package com.metabuild.modules.admin.audit.persistence;
import com.metabuild.modules.admin.auth.application.LoginAuditPort;import com.metabuild.shared.kernel.UuidV7Generator;import java.util.UUID;import org.jooq.DSLContext;import org.slf4j.*;import org.springframework.transaction.*;import org.springframework.transaction.support.TransactionTemplate;
/** 认证语义不被审计库故障污染；独立事务只入 outbox，实体日志由 worker 重试。 */
public final class JooqLoginAuditWriter implements LoginAuditPort {private static final Logger LOG=LoggerFactory.getLogger(JooqLoginAuditWriter.class);private final DSLContext db;private final UuidV7Generator ids;private final TransactionTemplate requiresNew;public JooqLoginAuditWriter(DSLContext db,UuidV7Generator ids,PlatformTransactionManager manager){this.db=db;this.ids=ids;requiresNew=new TransactionTemplate(manager);requiresNew.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);}public void record(UUID userId,String username,boolean success,String failureCode,String ip,String userAgent){try{requiresNew.executeWithoutResult(ignored->db.execute("insert into mb_login_audit_outbox(id,user_id,username,success,failure_code,ip_address,user_agent) values(?,?,?,?,?,nullif(?,'')::inet,?)",ids.generate(),userId,username,success,failureCode,ip==null?"":ip,userAgent));}catch(RuntimeException failure){LOG.error("Login audit enqueue failed",failure);}}}
